import json, sys

def render_content(content):
    if isinstance(content, str):
        return content
    out = []
    if isinstance(content, list):
        for c in content:
            if not isinstance(c, dict):
                out.append(str(c))
                continue
            t = c.get('type')
            if t == 'text':
                out.append(c.get('text',''))
            elif t == 'tool_use':
                name = c.get('name')
                inp = c.get('input')
                s = json.dumps(inp)[:300]
                out.append(f"[TOOL_USE {name}] {s}")
            elif t == 'tool_result':
                cont = c.get('content')
                if isinstance(cont, list):
                    txt = ' '.join(x.get('text','') for x in cont if isinstance(x,dict))
                else:
                    txt = str(cont)
                out.append(f"[TOOL_RESULT] {txt[:400]}")
            elif t == 'thinking':
                out.append(f"[THINKING] {c.get('thinking','')[:200]}")
            else:
                out.append(f"[{t}] {json.dumps(c)[:200]}")
    return '\n'.join(out)

fname = sys.argv[1]
with open(fname) as f:
    for line in f:
        line = line.strip()
        if not line: continue
        try:
            obj = json.loads(line)
        except Exception:
            continue
        typ = obj.get('type')
        ts = obj.get('timestamp', '')
        if typ in ('user','assistant'):
            msg = obj.get('message', {})
            role = msg.get('role', typ)
            content = msg.get('content', '')
            text = render_content(content)
            agent = obj.get('agentId','')
            prefix = f"{ts} [{role}]" + (f"(agent:{agent[:8]})" if agent else "")
            if text.strip():
                print(prefix)
                print(text)
                print('---')
EOF
